<template><v-container class="py-8 py-md-12" max-width="900"><div class="d-flex align-center justify-space-between mb-8"><div><h1 class="text-h4 page-title">我的友链</h1><p class="text-body-1 text-medium-emphasis mt-2">只显示 WordPress 备注中属于你的链接。</p></div><v-btn to="/submit" color="primary" prepend-icon="mdi-plus">申请友链</v-btn></div><v-alert v-if="message" :type="error ? 'error' : 'success'" variant="tonal" class="mb-4">{{ message }}</v-alert><v-card v-for="link in links" :key="link.id" rounded="xl" variant="outlined" class="mb-3"><v-list-item :title="link.name" :subtitle="link.url"><template #prepend><v-avatar color="primary-container"><v-img v-if="!failedIcons[link.id]" :src="siteIcon(link.url, link.avatar)" @error="failedIcons[link.id] = true"/><span v-if="failedIcons[link.id] || !siteIcon(link.url, link.avatar)">{{ link.name[0] }}</span></v-avatar></template><template #append><v-chip :color="link.status === 'approved' ? 'success' : link.status === 'rejected' ? 'grey' : 'warning'" variant="tonal" class="mr-2">{{ link.status === 'approved' ? '已公开' : link.status === 'rejected' ? '已隐藏' : '待审核' }}</v-chip><v-btn icon="mdi-delete-outline" variant="text" color="error" aria-label="删除友链" @click="remove(link)"/></template></v-list-item></v-card><v-alert v-if="loaded && !links.length" type="info" variant="tonal" rounded="xl">还没有属于你的友情链接。</v-alert><v-dialog v-model="deleteOpen" max-width="460"><v-card rounded="xl"><v-card-title class="pa-6">确认删除友情链接？</v-card-title><v-card-text class="pt-0">将删除「{{ deleteLink?.name }}」，此操作不可恢复。</v-card-text><v-card-actions class="pa-6 pt-0"><v-spacer/><v-btn variant="text" @click="deleteOpen = false">取消</v-btn><v-btn color="error" variant="tonal" :loading="deleting" @click="confirmRemove">删除</v-btn></v-card-actions></v-card></v-dialog></v-container></template>
<script setup lang="ts">import { onMounted, reactive, ref } from 'vue'; import { siteIcon } from '../icon'; const links = ref<any[]>([]); const failedIcons = reactive<Record<string, boolean>>({}); const loaded = ref(false); const message = ref(''); const error = ref(false); const deleteOpen = ref(false); const deleting = ref(false); const deleteLink = ref<any | null>(null); onMounted(async () => { links.value = (await fetch('/api/links/mine').then(r => r.json())).links || []; loaded.value = true }); function remove(link: any) { deleteLink.value = link; deleteOpen.value = true } async function confirmRemove() { if (!deleteLink.value) return; deleting.value = true; const r = await fetch(`/api/links/${deleteLink.value.id}`, { method: 'DELETE' }); deleting.value = false; if (r.ok) { links.value = links.value.filter(x => x.id !== deleteLink.value.id); deleteOpen.value = false; deleteLink.value = null } else { error.value = true; message.value = '删除失败' } }</script>
